/// struct StellarValue
/// {
///     Hash txSetHash;      // transaction set to apply to previous ledger
///     TimePoint closeTime; // network close time
///
///     // upgrades to apply to the previous ledger (usually empty)
///     // this is a vector of encoded 'LedgerUpgrade' so that nodes can drop
///     // unknown steps during consensus if needed.
///     // see notes below on 'LedgerUpgrade' for more detail
///     // max size is dictated by number of upgrade types (+ room for future)
///     UpgradeType upgrades<6>;
///
///     // reserved for future use
///     union switch (StellarValueType v)
///     {
///     case STELLAR_VALUE_BASIC:
///         void;
///     case STELLAR_VALUE_SIGNED:
///         LedgerCloseValueSignature lcValueSignature;
///     case STELLAR_VALUE_EMPTY_TX_SET:
///         struct
///         {
///             Hash txSetHash;
///             Hash previousLedgerHash;
///             uint32 previousLedgerVersion;
///             LedgerCloseValueSignature lcValueSignature;
///         } proposedValue;
///     case STELLAR_VALUE_SIGNED_MS:
///         struct
///         {
///             TimePointMs closeTimeMs; // closeTime == closeTimeMs / 1000
///             LedgerCloseValueSignature lcValueSignature;
///         } signedMsValue;
///     case STELLAR_VALUE_EMPTY_TX_SET_MS:
///         struct
///         {
///             TimePointMs closeTimeMs; // closeTime == closeTimeMs / 1000
///             Hash txSetHash;
///             Hash previousLedgerHash;
///             uint32 previousLedgerVersion;
///             LedgerCloseValueSignature lcValueSignature;
///         } proposedMsValue;
///     }
///     ext;
/// };
struct StellarValue {
  Hash txSetHash;
  TimePoint closeTime;
  BoundedVector<UpgradeType, 6> upgrades;
  StellarValueExt ext;
  bool operator==(const StellarValue&) const = default;
};
/// struct LedgerHeader
/// {
///     uint32 ledgerVersion;    // the protocol version of the ledger
///     Hash previousLedgerHash; // hash of the previous ledger header
///     StellarValue scpValue;   // what consensus agreed to
///     Hash txSetResultHash;    // the TransactionResultSet that led to this ledger
///     Hash bucketListHash;     // hash of the ledger state
///
///     uint32 ledgerSeq; // sequence number of this ledger
///
///     int64 totalCoins; // total number of stroops in existence.
///                       // 10,000,000 stroops in 1 XLM
///
///     int64 feePool;       // fees burned since last inflation run
///     uint32 inflationSeq; // inflation sequence number
///
///     uint64 idPool; // last used global ID, used for generating objects
///
///     uint32 baseFee;     // base fee per operation in stroops
///     uint32 baseReserve; // account base reserve in stroops
///
///     uint32 maxTxSetSize; // maximum size a transaction set can be
///
///     Hash skipList[4]; // hashes of ledgers in the past. allows you to jump back
///                       // in time without walking the chain back ledger by ledger
///                       // each slot contains the oldest ledger that is mod of
///                       // either 50  5000  50000 or 500000 depending on index
///                       // skipList[0] mod(50), skipList[1] mod(5000), etc
///
///     // reserved for future use
///     union switch (int v)
///     {
///     case 0:
///         void;
///     case 1:
///         LedgerHeaderExtensionV1 v1;
///     }
///     ext;
/// };
struct LedgerHeader {
  uint32 ledgerVersion;
  Hash previousLedgerHash;
  StellarValue scpValue;
  Hash txSetResultHash;
  Hash bucketListHash;
  uint32 ledgerSeq;
  int64 totalCoins;
  int64 feePool;
  uint32 inflationSeq;
  uint64 idPool;
  uint32 baseFee;
  uint32 baseReserve;
  uint32 maxTxSetSize;
  std::array<Hash, 4> skipList;
  LedgerHeaderExt ext;
  bool operator==(const LedgerHeader&) const = default;
};
